head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 0. gridview의 displayMode='value'로 설정한다.
    //Set displayMode = 'value' in gridview.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4_cell_0_0').setAttribute('displayMode', 'value')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 0. gridview의 displayMode='value'로 설정된다.
    //Set to displayMode = 'value' in gridview.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_4_cell_0_0').getAttribute('displayMode') == 'value'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일을 실행하여 name2항목의 displayMode값을 확인한다.(value값 0001보여지면 정상)
    // Run the sample file to check the displayMode value of the name2 entry (normal if value value 0001 is shown).
    //Verify 1. name2항목의 value값인 '0001'값이 gridView에 보여진다. (이전에는 vlaue모드가 없었고 label값인 aa가 보여짐)     
    //  The value of '0001' which is the value of the name2 item is shown in gridView.(Previously there was no vlaue mode and the label value aa is shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_4_cell_0_0').innerText == '0001'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.test1 = [{
        "col1": "a",
        "col2": "0001"
    }, {
        "col1": "a",
        "col2": "0002"
    }, {
        "col1": "a",
        "col2": "0003"
    }, {
        "col1": "a",
        "col2": "0004"
    }, {
        "col1": "a",
        "col2": "0005"
    }];
    dc_c01.setJSON(test1);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 25-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
